from collections import deque
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    # Helper to test if a cell is inside grid and free
    def free(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Validate start and goal
    if not (free(*start) and free(*goal)):
        return [] if start != goal else ([] if not free(*start) else [start])

    if start == goal:
        return [start]

    # BFS to find any path
    q = deque([start])
    prev = {start: None}
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
            if free(nr, nc) and nxt not in prev:
                prev[nxt] = (r, c)
                if nxt == goal:
                    # reconstruct path
                    path = [goal]
                    while path[-1] != start:
                        path.append(prev[path[-1]])
                    path.reverse()
                    return path
                q.append(nxt)

    # No path found
    return []
