def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#':
        return []
    if grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    from collections import deque

    queue = deque([start])
    visited = {start: None}
    found = False

    while queue:
        curr = queue.popleft()
        if curr == goal:
            found = True
            break

        r, c = curr
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited[(nr, nc)] = curr
                queue.append((nr, nc))

    if not found:
        return []

    path = []
    node = goal
    while node is not None:
        path.append(node)
        node = visited[node]

    return path[::-1]
